<?php
if(!defined('ABSPATH')) exit;

function bhc_catalog_scale_schema(){
 return ['external_id','sku','brand_fa','brand_latin','category','subcategory','model','source_url','source_type','source_checked_at','source_evidence','description_fa','short_description_fa','specs_json','highlights','faq','warranty','shipping_note','image_reference_url','image_prompt','image_status','review_status'];
}

function bhc_catalog_scale_image_prompt($product){
 if(!$product||!is_object($product)) return '';
 $sku=$product->get_sku()?:'SKU-NOT-SET';
 $name=$product->get_name();
 $model=get_post_meta($product->get_id(),'_bhc_model',true)?:$sku;
 $brand='';$terms=wp_get_post_terms($product->get_id(),'pa_brand',['fields'=>'names']);if(!is_wp_error($terms)&&$terms)$brand=$terms[0];
 return "Use the supplied verified reference image as the single source of truth for the exact product {$name}. Brand: {$brand}. Model/SKU: {$model} / {$sku}. Create a premium photorealistic ecommerce catalog image, exact silhouette, proportions, materials, colors, control layout, labels, logo and model identity preserved. Front three-quarter view, full product visible, centered, 70–85mm commercial lens, soft studio lighting, physically accurate contact shadow, 4K, 4096px long edge, transparent background with true alpha channel, isolated cutout, no floor, no wall, no room, no props, no packaging, no people, no text, no price, no watermark, no invented parts, no fabricated logo, no altered model. If the exact reference image is missing or ambiguous, stop and do not generate an image.";
}

function bhc_catalog_scale_metrics(){
 global $wpdb;
 $products=function_exists('wc_get_products')?count(wc_get_products(['status'=>['publish','draft','pending','private'],'limit'=>-1,'return'=>'ids'])):(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type='product' AND post_status IN ('publish','draft','pending','private')");
 $reference=(int)$wpdb->get_var("SELECT COUNT(DISTINCT p.ID) FROM {$wpdb->posts} p JOIN {$wpdb->postmeta} m ON m.post_id=p.ID AND m.meta_key='_bhc_source_url' WHERE p.post_type='product'");
 $prompts=(int)$wpdb->get_var("SELECT COUNT(DISTINCT p.ID) FROM {$wpdb->posts} p JOIN {$wpdb->postmeta} m ON m.post_id=p.ID AND m.meta_key='_bhc_image_prompt' WHERE p.post_type='product'");
 $structured=(int)$wpdb->get_var("SELECT COUNT(DISTINCT p.ID) FROM {$wpdb->posts} p JOIN {$wpdb->postmeta} m ON m.post_id=p.ID AND m.meta_key='_bhc_structured_specs' AND m.meta_value<>'' WHERE p.post_type='product'");
 $exact=(int)$wpdb->get_var("SELECT COUNT(DISTINCT p.ID) FROM {$wpdb->posts} p JOIN {$wpdb->postmeta} m ON m.post_id=p.ID AND m.meta_key='_bhc_source_type' AND m.meta_value IN ('exact_model_page','exact_retailer_page','official_exact_model_page') WHERE p.post_type='product'");
 $verified=(int)$wpdb->get_var("SELECT COUNT(DISTINCT p.ID) FROM {$wpdb->posts} p JOIN {$wpdb->postmeta} m ON m.post_id=p.ID AND m.meta_key='_bhc_image_generation_status' AND m.meta_value='product_specific_generated' WHERE p.post_type='product'");
 $content_complete=0;$image_references=0;$image_reference_ready=0;$ready=0;$ambiguous=0;$legacy_needs_source=0;$source_needs_exact=0;
 if(function_exists('wc_get_products'))foreach(wc_get_products(['status'=>['publish','draft','pending','private'],'limit'=>-1,'return'=>'objects']) as $product){
  $id=$product->get_id();$spec=(string)get_post_meta($id,'_bhc_structured_specs',true);$desc=trim(wp_strip_all_tags($product->get_description()));$short=trim(wp_strip_all_tags($product->get_short_description()));$faq=trim((string)get_post_meta($id,'_bhc_faq',true));$warranty=trim((string)get_post_meta($id,'_bhc_warranty',true));$shipping=trim((string)get_post_meta($id,'_bhc_shipping_note',true));
  if($spec!==''&&$desc!==''&&$short!==''&&$faq!==''&&$warranty!==''&&$shipping!=='')$content_complete++;
  if($spec!==''&&preg_match('/اعلام نشده|نیازمند کنترل|کنترل نهایی|نامشخص|ابهام|تایید شود/u',$spec))$ambiguous++;
  $image_url=(string)get_post_meta($id,'_bhc_image_reference_url',true);if($image_url!=='')$image_references++;
  if(function_exists('bhc_catalog_quality_report')){$report=bhc_catalog_quality_report($product);if(($report['state']??'')==='legacy_needs_source')$legacy_needs_source++;if(!empty($report['is_reference'])&&!empty($report['checks'])&&empty($report['checks']['source_exact']))$source_needs_exact++;if(!empty($report['checks']['image_reference_url_valid'])&&!empty($report['checks']['image_reference_evidence'])&&!empty($report['checks']['image_reference_checked']))$image_reference_ready++;if(($report['state']??'')==='ready_for_release')$ready++;}
 }
 return compact('products','reference','prompts','structured','exact','verified','content_complete','image_references','image_reference_ready','ready','ambiguous','legacy_needs_source','source_needs_exact');
}

add_action('init',function(){
 if(!get_option('bhc_catalog_content_backfill_v1')&&function_exists('wc_get_products')){
  foreach(wc_get_products(['status'=>['publish','draft','pending','private'],'limit'=>-1,'return'=>'objects']) as $product){$id=$product->get_id();if(!get_post_meta($id,'_bhc_source_url',true)||!get_post_meta($id,'_bhc_structured_specs',true))continue;if(!get_post_meta($id,'_bhc_faq',true))update_post_meta($id,'_bhc_faq','آیا محصول موجود است؟ | وضعیت فعلی ناموجود است و قبل از عرضه باید کنترل شود.\nآیا مشخصات نهایی است؟ | منبع در کاتالوگ ثبت شده است؛ تطبیق نسخه منطقه‌ای پیش از انتشار لازم است.\nآیا تصویر اختصاصی آماده است؟ | تا تأیید مرجع دقیق، خیر.');if(!get_post_meta($id,'_bhc_warranty',true))update_post_meta($id,'_bhc_warranty','گارانتی و خدمات پس از فروش باید بر اساس بازار ایران و نمایندگی مجاز تأیید شود.');if(!get_post_meta($id,'_bhc_shipping_note',true))update_post_meta($id,'_bhc_shipping_note','ارسال پس از تأیید موجودی، اصالت، مدل، نسخه منطقه‌ای و شرایط گارانتی انجام می‌شود.');}
  update_option('bhc_catalog_content_backfill_v1',['at'=>current_time('mysql')],false);
 }
},60);

add_action('admin_menu',function(){
 add_submenu_page('baharaan-commerce','مقیاس کاتالوگ ۱۰ هزار کالا','مقیاس کاتالوگ ۱۰K','manage_options','bhc-catalog-scale','bhc_catalog_scale_page',31);
 add_submenu_page('baharaan-commerce','گزارش کنترل کیفیت کاتالوگ','کنترل کیفیت کاتالوگ','manage_options','bhc-catalog-quality','bhc_catalog_quality_admin_page',32);
