function bhc_catalog_quality_admin_page(){
 if(!current_user_can('manage_options'))return;
 echo '<div class="wrap" dir="rtl"><h1>کنترل کیفیت کاتالوگ</h1><p>این گزارش برای جلوگیری از انتشار مدل اشتباه، مشخصات ناقص یا تصویر غیرمرتبط طراحی شده است. «مرجع» به‌معنی محصول تأییدشده نهایی نیست.</p><table class="widefat striped"><thead><tr><th>محصول / SKU</th><th>امتیاز</th><th>وضعیت</th><th>موارد ناقص</th><th>ویرایش</th></tr></thead><tbody>';
 if(function_exists('wc_get_products'))foreach(wc_get_products(['status'=>['publish','draft','pending','private'],'limit'=>-1,'return'=>'objects']) as $product){$report=function_exists('bhc_catalog_quality_report')?bhc_catalog_quality_report($product):['score'=>0,'state'=>'unknown','checks'=>[]];$missing=[];foreach((array)($report['checks']??[]) as $key=>$ok)if(!$ok)$missing[]=$key;$edit=get_edit_post_link($product->get_id(),'');echo '<tr><td>'.esc_html($product->get_name()).'<br><code>'.esc_html($product->get_sku()).'</code></td><td>'.esc_html((string)($report['score']??0)).'%</td><td>'.esc_html((string)($report['state']??'unknown')).'</td><td>'.esc_html($missing?implode('، ',$missing):'ندارد').'</td><td><a href="'.esc_url($edit).'">باز کردن محصول</a></td></tr>';}
 echo '</tbody></table></div>';
}
function bhc_catalog_scale_page(){
 if(!current_user_can('manage_options'))return;
 $m=bhc_catalog_scale_metrics();$target=10000;$template=wp_nonce_url(admin_url('admin-post.php?action=bhc_catalog_scale_template'),'bhc_catalog_scale_template');$source_register=wp_nonce_url(admin_url('admin-post.php?action=bhc_catalog_source_register'),'bhc_catalog_source_register');
 $source_import_nonce=wp_create_nonce('bhc_catalog_source_import');echo '<section class="notice notice-info" dir="rtl"><p><strong>اصلاح دسته‌ای منبع دقیق مدل:</strong> فایل رجیستر را دانلود کنید، URL صفحه دقیق مدل و مدرک بررسی را تکمیل کنید و از همین‌جا وارد کنید. این عملیات فقط منبع را اصلاح می‌کند و تأیید نهایی محصول را انجام نمی‌دهد.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" enctype="multipart/form-data"><input type="hidden" name="action" value="bhc_catalog_source_import"><input type="hidden" name="_wpnonce" value="'.esc_attr($source_import_nonce).'" /><input type="file" name="source_csv" accept=".csv,text/csv" required> <button class="button" type="submit">ثبت منابع دقیق</button></form></section>';
 echo '<div class="wrap" dir="rtl"><h1>مقیاس کاتالوگ ۱۰٬۰۰۰ کالا</h1><p>هیچ ردیف بدون منبع دقیق، SKU یکتا، مشخصات ساختاریافته و وضعیت تصویر قابل انتشار نیست. این صفحه فقط وضعیت واقعی را نشان می‌دهد.</p><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;max-width:1000px">';
 foreach(['products'=>'محصول فعلی','reference'=>'دارای منبع','legacy_needs_source'=>'رکورد بدون منبع','source_needs_exact'=>'نیازمند منبع دقیق مدل','prompts'=>'دارای پرامپت','structured'=>'دارای مشخصات ساختاریافته','exact'=>'منبع دقیق مدل','content_complete'=>'محتوای کامل','image_references'=>'URL مرجع تصویر','image_reference_ready'=>'مرجع تصویر قابل ممیزی','verified'=>'تصویر اختصاصی تأییدشده','ready'=>'آماده انتشار'] as $key=>$label){$v=(int)($m[$key]??0);echo '<div style="padding:16px;border:1px solid #ccd6e0;border-radius:8px;background:#fff"><b style="font-size:24px">'.esc_html(number_format_i18n($v)).'</b><br><span>'.esc_html($label).'</span></div>';}
 echo '</div><h2>هدف و فاصله</h2><p><strong>'.esc_html(number_format_i18n($m['products'])).'</strong> از <strong>'.esc_html(number_format_i18n($target)).'</strong> محصول ساخته شده است؛ فاصله فعلی: <strong>'.esc_html(number_format_i18n(max(0,$target-(int)$m['products']))).'</strong> رکورد.</p><p><a class="button button-primary" href="'.esc_url($template).'">دانلود قالب ورود کاتالوگ</a> <a class="button" href="'.esc_url($source_register).'">دانلود رجیستر اصلاح منبع مدل</a></p><h2>ورود کنترل‌شده</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" enctype="multipart/form-data"><input type="hidden" name="action" value="bhc_catalog_scale_import"><input type="hidden" name="_wpnonce" value="'.esc_attr(wp_create_nonce('bhc_catalog_scale_import')).'"><input type="file" name="catalog_csv" accept=".csv,text/csv" required><button class="button button-primary" type="submit">اعتبارسنجی و ورود به‌صورت پیش‌نویس</button></form><p>هر ردیف با خطای منبع، SKU، مدل، برند، دسته یا JSON مشخصات رد می‌شود؛ رکوردهای پذیرفته‌شده ابتدا پیش‌نویس هستند.</p><h2>قرارداد داده اجباری</h2><p><code>'.esc_html(implode(' · ',bhc_catalog_scale_schema())).'</code></p><p>پرامپت تصویر الزاماً شامل مرجع دقیق، 4K، 4096px، true alpha، transparent background، بدون پس‌زمینه و توقف در صورت نبود مرجع است.</p></div>';
}

add_action('admin_post_bhc_catalog_source_register',function(){if(!current_user_can('manage_options'))wp_die('دسترسی مجاز نیست');check_admin_referer('bhc_catalog_source_register');nocache_headers();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=baharan-exact-source-register.csv');echo "sku,product,model,current_source,exact_source_url,source_type,source_evidence,source_checked_at\n";if(function_exists('wc_get_products'))foreach(wc_get_products(['status'=>['publish','draft','pending','private'],'limit'=>-1,'orderby'=>'name','order'=>'ASC','return'=>'objects']) as $product){$id=$product->get_id();$row=[$product->get_sku(),$product->get_name(),get_post_meta($id,'_bhc_model',true),get_post_meta($id,'_bhc_source_url',true),get_post_meta($id,'_bhc_source_url',true),get_post_meta($id,'_bhc_source_type',true),get_post_meta($id,'_bhc_source_evidence',true),get_post_meta($id,'_bhc_source_checked_at',true)];echo implode(',',array_map(function($value){return '"'.str_replace('"','""',(string)$value).'"';},$row)).PHP_EOL;}exit;});

add_action('admin_post_bhc_catalog_source_import',function(){if(!current_user_can('manage_options'))wp_die('دسترسی مجاز نیست');check_admin_referer('bhc_catalog_source_import');if(empty($_FILES['source_csv']['tmp_name'])||!is_uploaded_file($_FILES['source_csv']['tmp_name']))wp_die('فایل CSV معتبر نیست');$fh=fopen($_FILES['source_csv']['tmp_name'],'r');$header=fgetcsv($fh);$required=['sku','product','model','current_source','exact_source_url','source_type','source_evidence','source_checked_at'];$header=array_map('trim',(array)$header);$missing=array_diff($required,$header);if($missing){fclose($fh);wp_die('ستون‌های CSV ناقص است: '.esc_html(implode(', ',$missing)));}$pos=array_flip($header);$updated=0;$rejected=0;$errors=[];$row_number=1;while(($row=fgetcsv($fh))!==false){$row_number++;$sku=sanitize_text_field($row[$pos['sku']]??'');$url=esc_url_raw($row[$pos['exact_source_url']]??'');$type=sanitize_key($row[$pos['source_type']]??'');$evidence=sanitize_textarea_field($row[$pos['source_evidence']]??'');$checked=sanitize_text_field($row[$pos['source_checked_at']]??'');$id=function_exists('wc_get_product_id_by_sku')?wc_get_product_id_by_sku($sku):0;$valid=$id&&$url&&wp_http_validate_url($url)&&in_array($type,['exact_model_page','exact_retailer_page'],true)&&$evidence!==''&&$checked!=='';if(!$valid){$rejected++;if(count($errors)<30)$errors[]='ردیف '.$row_number.': SKU یا منبع دقیق/نوع/مدرک/تاریخ نامعتبر است';continue;}update_post_meta($id,'_bhc_source_url',$url);update_post_meta($id,'_bhc_source_type',$type);update_post_meta($id,'_bhc_source_evidence',$evidence);update_post_meta($id,'_bhc_source_checked_at',$checked);update_post_meta($id,'_bhc_catalog_quality_state','reference_needs_verification');update_post_meta($id,'_bhc_verification_status','needs_editor_review');$updated++;}fclose($fh);update_option('bhc_catalog_source_import_last',['updated'=>$updated,'rejected'=>$rejected,'errors'=>$errors,'at'=>current_time('mysql')],false);wp_safe_redirect(admin_url('admin.php?page=bhc-catalog-scale&sources_updated='.$updated.'&sources_rejected='.$rejected));exit;});
add_action('admin_notices',function(){if(sanitize_key($_GET['page']??'')!=='bhc-catalog-scale'||!current_user_can('manage_options')||!isset($_GET['sources_updated']))return;echo '<div class="notice notice-success is-dismissible"><p>'.esc_html(number_format_i18n(absint($_GET['sources_updated']))).' منبع دقیق مدل ثبت شد؛ '.esc_html(number_format_i18n(absint($_GET['sources_rejected']??0))).' ردیف رد شد. این تغییر هنوز به‌معنی تأیید نهایی محصول نیست.</p></div>';});

add_action('admin_post_bhc_catalog_scale_import',function(){
 if(!current_user_can('manage_options'))wp_die('دسترسی مجاز نیست');
 check_admin_referer('bhc_catalog_scale_import');
 if(empty($_FILES['catalog_csv']['tmp_name'])||!is_uploaded_file($_FILES['catalog_csv']['tmp_name']))wp_die('فایل CSV معتبر نیست');
 $fh=fopen($_FILES['catalog_csv']['tmp_name'],'r');$header=fgetcsv($fh);$required=bhc_catalog_scale_schema();$header=array_map('trim',(array)$header);$missing=array_diff($required,$header);if($missing){fclose($fh);wp_die('ستون‌های اجباری ناقص است: '.esc_html(implode(', ',$missing)));}
 $positions=array_flip($header);$created=0;$rejected=0;$errors=[];$row_number=1;$seen_skus=[];
 while(($row=fgetcsv($fh))!==false){$row_number++;$data=[];foreach($required as $key)$data[$key]=trim((string)($row[$positions[$key]]??''));$row_error='';$sku=sanitize_text_field($data['sku']);$brand=sanitize_text_field($data['brand_fa']);$category=sanitize_text_field($data['category']);$model=sanitize_text_field($data['model']);$source=esc_url_raw($data['source_url']);$specs=json_decode($data['specs_json'],true);
  $image_reference=esc_url_raw($data['image_reference_url']);
  if($sku===''||$brand===''||$category===''||$model===''||!$source||!wp_http_validate_url($source)||$data['source_evidence']===''||!$image_reference||!wp_http_validate_url($image_reference))$row_error='SKU، برند، دسته، مدل، مدرک منبع یا URL مرجع تصویر ناقص/نامعتبر است';
  elseif(!is_array($specs)||!$specs)$row_error='specs_json باید JSON شیء معتبر و غیرخالی باشد';
  elseif(isset($seen_skus[$sku]))$row_error='SKU در همین فایل CSV تکراری است';
  elseif(function_exists('wc_get_product_id_by_sku')&&wc_get_product_id_by_sku($sku))$row_error='SKU از قبل وجود دارد';
  if($row_error){$rejected++;if(count($errors)<30)$errors[]='ردیف '.$row_number.': '.$row_error;continue;}
  $seen_skus[$sku]=true;
  $product=new WC_Product_Simple();$product->set_name($brand.' '.$category.' مدل '.$model);$product->set_sku($sku);$product->set_status('draft');$product->set_catalog_visibility('hidden');$product->set_stock_status('outofstock');$product->set_description(wp_kses_post($data['description_fa']));$product->set_short_description(sanitize_textarea_field($data['short_description_fa']));$id=$product->save();
  if(!$id){$rejected++;continue;}
  wp_set_object_terms($id,$category,'product_cat',true);wp_set_object_terms($id,$brand,'pa_brand',true);
  update_post_meta($id,'_bhc_external_id',sanitize_text_field($data['external_id']));update_post_meta($id,'_bhc_source_url',$source);update_post_meta($id,'_bhc_source_type',sanitize_key($data['source_type']));update_post_meta($id,'_bhc_source_checked_at',sanitize_text_field($data['source_checked_at']));update_post_meta($id,'_bhc_source_evidence',sanitize_textarea_field($data['source_evidence']));update_post_meta($id,'_bhc_image_reference_url',$image_reference);update_post_meta($id,'_bhc_image_status',sanitize_key($data['image_status']?:'awaiting_reference'));update_post_meta($id,'_bhc_review_status',sanitize_key($data['review_status']?:'needs_review'));update_post_meta($id,'_bhc_model',$model);update_post_meta($id,'_bhc_brand_latin',sanitize_text_field($data['brand_latin']));update_post_meta($id,'_bhc_structured_specs',wp_json_encode($specs,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));update_post_meta($id,'_bhc_highlights',sanitize_textarea_field($data['highlights']));update_post_meta($id,'_bhc_faq',sanitize_textarea_field($data['faq']));update_post_meta($id,'_bhc_warranty',sanitize_text_field($data['warranty']));update_post_meta($id,'_bhc_shipping_note',sanitize_text_field($data['shipping_note']));update_post_meta($id,'_bhc_verification_status','needs_editor_review');update_post_meta($id,'_bhc_catalog_quality_state','reference_needs_verification');update_post_meta($id,'_bhc_image_generation_status','awaiting_product_reference');$saved=bhc_catalog_scale_image_prompt($product);if($saved)update_post_meta($id,'_bhc_image_prompt',$saved);$created++;
 }
 fclose($fh);update_option('bhc_catalog_last_import',['created'=>$created,'rejected'=>$rejected,'errors'=>$errors,'at'=>current_time('mysql')],false);wp_safe_redirect(add_query_arg(['page'=>'bhc-catalog-scale','imported'=>$created,'rejected'=>$rejected],admin_url('admin.php')));exit;
});

