/* Publish documented model pages without exposing unverified inventory. */
add_action('init',function(){
 if(get_option('bhc_documented_pages_published_v41')||!function_exists('wc_get_products'))return;
 $changed=0;
 foreach(wc_get_products(['status'=>'draft','limit'=>-1,'return'=>'objects']) as $product){
  $id=$product->get_id();
  $specs=get_post_meta($id,'_bhc_structured_specs',true);
  $source=get_post_meta($id,'_bhc_source_url',true);
  $type=get_post_meta($id,'_bhc_source_type',true);
  if(!$specs||!$source||!in_array($type,['exact_model_page','exact_retailer_page'],true))continue;
  wp_update_post(['ID'=>$id,'post_status'=>'publish']);
  $product->set_catalog_visibility('hidden');
  $product->set_stock_status('outofstock');
  $product->save();
  update_post_meta($id,'_bhc_catalog_page_state','published_hidden_outofstock');
  $changed++;
 }
 update_option('bhc_documented_pages_published_v41',['changed'=>$changed,'at'=>current_time('mysql')],false);
},41);

