/* Quarantine records with only a broad/generic source until exact model evidence is registered. */
add_action('init',function(){
 if(get_option('bhc_source_quarantine_v44')||!function_exists('wc_get_products'))return;
 $changed=0;
 foreach(wc_get_products(['status'=>['publish','draft','pending','private'],'limit'=>-1,'return'=>'objects']) as $product){
  $id=$product->get_id();
  $type=(string)get_post_meta($id,'_bhc_source_type',true);
  if(in_array($type,['exact_model_page','exact_retailer_page'],true))continue;
  $source=(string)get_post_meta($id,'_bhc_source_url',true);
  if($source==='')continue;
  wp_update_post(['ID'=>$id,'post_status'=>'draft']);
  $product->set_catalog_visibility('hidden');
  $product->set_stock_status('outofstock');
  $product->save();
  update_post_meta($id,'_bhc_catalog_quality_state','source_needs_exact');
  update_post_meta($id,'_bhc_verification_status','needs_editor_review');
  update_post_meta($id,'_bhc_source_quarantine_reason','منبع فعلی عمومی/غیردقیق است؛ صفحه دقیق مدل و مدرک مشخصات لازم است.');
  $changed++;
 }
 update_option('bhc_source_quarantine_v44',['changed'=>$changed,'at'=>current_time('mysql')],false);
},44);

