add_action('init',function(){
 if(get_option('bhc_catalog_prompt_contract_v1'))return;
 if(!function_exists('wc_get_products'))return;
 foreach(wc_get_products(['status'=>['publish','draft','pending','private'],'limit'=>-1,'return'=>'objects']) as $product){
  $old=(string)get_post_meta($product->get_id(),'_bhc_image_prompt',true);
  $prompt=bhc_catalog_scale_image_prompt($product);
  if($prompt&&($old===''||strpos($old,'true alpha channel')===false))update_post_meta($product->get_id(),'_bhc_image_prompt',$prompt);
 }
 update_option('bhc_catalog_prompt_contract_v1',['at'=>current_time('mysql')],false);
},30);

/* SEO contract: metadata is generated only from the verified catalog record.
 * It is intentionally separate from the visible copy so an editor can audit
 * the source, model and wording before a product is released. */
function bhc_catalog_seo_contract($product){
 if(!$product||!is_object($product))return [];
 $id=$product->get_id();$name=trim(wp_strip_all_tags($product->get_name()));
 $brand='';$brand_terms=wp_get_post_terms($id,'pa_brand',['fields'=>'names']);
 if(!is_wp_error($brand_terms)&&$brand_terms)$brand=trim((string)$brand_terms[0]);
 $model=trim((string)get_post_meta($id,'_bhc_model',true));
 $source=(string)get_post_meta($id,'_bhc_source_url',true);
 $categories=wp_get_post_terms($id,'product_cat',['fields'=>'names']);
 $category=(!is_wp_error($categories)&&$categories)?trim((string)$categories[0]):'لوازم خانگی';
 $status=$product->is_in_stock()?'موجود':'ناموجود';
 $title=trim($name.' | '.$status.' | بهاران هوم');
 $summary=trim(wp_strip_all_tags($product->get_short_description()));
 $description=$summary?:($brand.' '.$category.' مدل '.($model?:$name).'؛ مشخصات فنی مستند، منبع بررسی‌شده و وضعیت '.$status.' در بهاران هوم.');
 $description=wp_trim_words($description,30,'…');
 return ['title'=>mb_substr($title,0,65),'description'=>mb_substr($description,0,155),'focus_keyword'=>trim(($brand?$brand.' ':'').($model?:$category)),'source_url'=>$source,'generated_at'=>current_time('mysql')];
}

