/* Canonical taxonomy normalization v1: remove the broad duplicate category
 * from model-specific products while preserving unrelated classifications. */
add_action('init',function(){
 if(get_option('bhc_catalog_taxonomy_normalized_v1')||!function_exists('wc_get_products'))return;
 $rules=[
  ['needles'=>['لباسشویی','ماشین لباسشویی'],'canonical'=>'لباسشویی','remove'=>['شست‌وشو']],
  ['needles'=>['ظرفشویی','ماشین ظرفشویی'],'canonical'=>'ظرفشویی','remove'=>['شست‌وشو']],
  ['needles'=>['جاروبرقی','جارو شارژی','جارو شارژی'],'canonical'=>'جاروبرقی','remove'=>['نظافت']],
  ['needles'=>['یخچال','فریزر'],'canonical'=>'یخچال و فریزر','remove'=>[]],
  ['needles'=>['تلویزیون'],'canonical'=>'تلویزیون','remove'=>[]],
 ];
 $changed=0;
 foreach(wc_get_products(['status'=>['publish','draft','pending','private'],'limit'=>-1,'return'=>'objects']) as $product){$name=$product->get_name();foreach($rules as $rule){$match=false;foreach($rule['needles'] as $needle){if(mb_stripos($name,$needle)!==false){$match=true;break;}}if(!$match)continue;wp_set_object_terms($product->get_id(),$rule['canonical'],'product_cat',true);foreach($rule['remove'] as $remove)wp_remove_object_terms($product->get_id(),$remove,'product_cat');$changed++;break;}}
 update_option('bhc_catalog_taxonomy_normalized_v1',['changed'=>$changed,'at'=>current_time('mysql')],false);
},37);

